import{_ as r,o as a,c as o,ak as t}from"./chunks/framework.DIgTxpuq.js";const m=JSON.parse('{"title":"Interface: ModifierHandler<N>","description":"","frontmatter":{},"headers":[],"relativePath":"api/rpg-dice-roller/namespaces/modifiers/interfaces/ModifierHandler.md","filePath":"api/rpg-dice-roller/namespaces/modifiers/interfaces/ModifierHandler.md","lastUpdated":1794042109000}'),i={name:"api/rpg-dice-roller/namespaces/modifiers/interfaces/ModifierHandler.md"};function d(s,e,l,n,c,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<p><a href="./../../../../">@dice-roller/rpg-dice-roller</a> / <a href="./../">modifiers</a> / ModifierHandler</p><h1 id="interface-modifierhandler-n" tabindex="-1">Interface: ModifierHandler&lt;N&gt; <a class="header-anchor" href="#interface-modifierhandler-n" aria-label="Permalink to &quot;Interface: ModifierHandler\\&lt;N\\&gt;&quot;">​</a></h1><p>Defined in: <a href="https://github.com/dice-roller/rpg-dice-roller/blob/e5fc57b800027d5376a4b67c69ac191796693323/src/modifiers/types.ts#L29" target="_blank" rel="noreferrer">src/modifiers/types.ts:29</a></p><p>The behaviour of a modifier.</p><p>Handlers are registered by <code>name</code> in the <code>ModifierRegistry</code>, and run in ascending <code>order</code> regardless of notation order; equal orders retain notation order. Implementations should not mutate their input: return a new array, copying changed items with the result helpers. Unchanged items may be reused.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to &quot;Type Parameters&quot;">​</a></h2><h3 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h3><p><code>N</code> <em>extends</em> <a href="./../../ast/type-aliases/ModifierNode.html"><code>ModifierNode</code></a> = <a href="./../../ast/type-aliases/ModifierNode.html"><code>ModifierNode</code></a></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="appliesto" tabindex="-1">appliesTo <a class="header-anchor" href="#appliesto" aria-label="Permalink to &quot;appliesTo&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>appliesTo</strong>: readonly <a href="./../type-aliases/ModifierTarget.html"><code>ModifierTarget</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/dice-roller/rpg-dice-roller/blob/e5fc57b800027d5376a4b67c69ac191796693323/src/modifiers/types.ts#L35" target="_blank" rel="noreferrer">src/modifiers/types.ts:35</a></p><p>Targets on which the evaluator permits this handler.</p><hr><h3 id="grouphandling" tabindex="-1">groupHandling? <a class="header-anchor" href="#grouphandling" aria-label="Permalink to &quot;groupHandling?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>groupHandling?</strong>: <code>&quot;flatten&quot;</code> | <code>&quot;each-pool&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/dice-roller/rpg-dice-roller/blob/e5fc57b800027d5376a4b67c69ac191796693323/src/modifiers/types.ts#L49" target="_blank" rel="noreferrer">src/modifiers/types.ts:49</a></p><p>How the handler treats the dice inside a roll group. By default it only gets the members.</p><ul><li><code>flatten</code>: a group with a single expression gets the dice of every pool in it, flattened, instead of its member (keep, drop: <code>{4d6+2d8}k2</code> keeps the 2 highest dice)</li><li><code>each-pool</code>: gets the members of each group, then the dice of each pool, separately (sort: nested members are sorted by total, and the dice within each pool)</li></ul><p>Pools in a pool&#39;s quantity or die arguments aren&#39;t included. Flattening stops at nested groups; with multiple expressions it operates on members instead. Flattened dice are written back to their original pools, so returned dice must retain their pool association (e.g. by copying an input item with object spread). New, unassociated dice cause an <code>EvaluationError</code>.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>N</code>[<code>&quot;name&quot;</code>]</p></blockquote><p>Defined in: <a href="https://github.com/dice-roller/rpg-dice-roller/blob/e5fc57b800027d5376a4b67c69ac191796693323/src/modifiers/types.ts#L31" target="_blank" rel="noreferrer">src/modifiers/types.ts:31</a></p><p>The existing AST modifier name this handler implements.</p><hr><h3 id="order" tabindex="-1">order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;order&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>order</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/dice-roller/rpg-dice-roller/blob/e5fc57b800027d5376a4b67c69ac191796693323/src/modifiers/types.ts#L33" target="_blank" rel="noreferrer">src/modifiers/types.ts:33</a></p><p>Execution order; lower runs first.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="apply" tabindex="-1">apply() <a class="header-anchor" href="#apply" aria-label="Permalink to &quot;apply()&quot;">​</a></h3><blockquote><p><strong>apply</strong>&lt;<code>T</code>&gt;(<code>items</code>, <code>input</code>): <code>T</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/dice-roller/rpg-dice-roller/blob/e5fc57b800027d5376a4b67c69ac191796693323/src/modifiers/types.ts#L58" target="_blank" rel="noreferrer">src/modifiers/types.ts:58</a></p><p>Applies the modifier.</p><p><code>items</code> are die results for a pool, or group members for a group (or die results, as set by <code>groupHandling</code>). Group calls, including calls for their pool dice, do not supply <code>die</code> or <code>rollDie</code>. The evaluator requires an array result.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to &quot;Type Parameters&quot;">​</a></h4><h5 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h5><p><code>T</code> <em>extends</em> <a href="./../../results/interfaces/ScoredItem.html"><code>ScoredItem</code></a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="items" tabindex="-1">items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;items&quot;">​</a></h5><p>readonly <code>T</code>[]</p><h5 id="input" tabindex="-1">input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;input&quot;">​</a></h5><p><a href="./ModifierInput.html"><code>ModifierInput</code></a>&lt;<code>N</code>&gt;</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>T</code>[]</p>',46)])])}const u=r(i,[["render",d]]);export{m as __pageData,u as default};
